css:
body {
    font-family: Arial, sans-serif;
    font-size: 13px;
    color: #000;
}

.header-table {
    width: 100%;
    margin-bottom: 10px;
}

.header-table td {
    vertical-align: top;
}

.title {
    text-align: center;
    font-weight: bold;
    text-decoration: underline;
    margin: 10px 0 20px;
    font-size: 16px;
}

.info-table td {
    padding: 4px 0 0;
}

.details-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 15px;
}

.details-table th {
    font-size: 12px;
    background: #8ea9da;
    color: white;
    padding: 8px;
    border: 1px solid #000;
}

.details-table td {
    font-size: 12px;
    border: 1px solid #000;
    padding: 8px;
}

.footer-text {
    margin-top: 25px;
    line-height: 1.6;
}
